python3 -c "
import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Find tables with 'saving' in them
def search_nested(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'saving' in str(k).lower():
                results.append((f'{path}.{k}', v))
            results.extend(search_nested(v, f'{path}.{k}'))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_nested(item, f'{path}[{i}]'))
    return results

results = search_nested(data)
for r in results:
    print(f'{r[0]}: {str(r[1])[:200]}')
"

